CREATE TABLE IF NOT EXISTS "sv_incidents" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "order_id" uuid REFERENCES "sv_orders"("id"), "cycle_id" uuid REFERENCES "sv_cycles"("id"), "kind" text NOT NULL, "severity" text DEFAULT 'high' NOT NULL, "detail" text NOT NULL, "dispatch_key" text, "status" text DEFAULT 'OPEN' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "resolved_at" timestamptz);
CREATE INDEX IF NOT EXISTS "sv_incidents_org_created_idx" ON "sv_incidents" ("organization_id", "created_at"); CREATE INDEX IF NOT EXISTS "sv_incidents_order_idx" ON "sv_incidents" ("order_id"); ALTER TABLE "sv_incidents" ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS "sv_cost_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "run_id" uuid REFERENCES "sv_runs"("id"), "provider" text NOT NULL, "amount_usd" numeric(12, 6) NOT NULL, "basis" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX IF NOT EXISTS "sv_cost_events_org_cycle_idx" ON "sv_cost_events" ("organization_id", "cycle_id"); CREATE INDEX IF NOT EXISTS "sv_cost_events_run_idx" ON "sv_cost_events" ("run_id"); ALTER TABLE "sv_cost_events" ENABLE ROW LEVEL SECURITY;
